// Creating custom iterable range object:
function createRange(start, end, step = 1) {
  return {
    [Symbol.iterator]() {
      let current = start;
      return {
        next() {
          if (current <= end) {
            const val = current;
            current += step;
            return { value: val, done: false };
          }
          return { value: undefined, done: true };
        }
      };
    }
  };
}
const nums = [...createRange(1, 5)];

